const formats={image:'Imagem',feed:'Imagem',video:'Reels',reels:'Reels',carousel:'Carrossel',story:'Story',text:'Texto'};
export function programmingItems(state,schedules=[],now=Date.now()){
 const content=(state.records?.content||[]).filter(c=>c.scheduledAt&&!['published','canceled','cancelled'].includes(c.status)).map(c=>({id:c.id,kind:'content',title:c.title,format:formats[c.format]||'Conteúdo',at:Date.parse(c.scheduledAt),label:['approved','scheduled'].includes(c.status)&&c.assetId?'Pronto':c.status==='review'?'Aprovar':'Em preparo',tone:['approved','scheduled'].includes(c.status)&&c.assetId?'ready':'review'}));
 const scheduled=schedules.filter(s=>!s.canceled&&(s.enabled||s.lastError||!s.lastRunAt)).map(s=>({id:s.id,kind:'generation',title:s.request?.prompt||'Criação programada',format:formats[s.request?.format]||'Conteúdo',at:s.nextAt,label:s.lastError?'Revisar':!s.enabled?'Pausada':!(state.company.policy?.schedulesEnabled??state.company.policy?.enabled)?'Pausada':'A gerar',tone:s.lastError?'review':'pending',schedule:s}));
 return [...content,...scheduled].filter(c=>Number.isFinite(c.at)).sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id)).map(c=>({...c,remaining:c.at<now?'Data passou':c.at-now<3600000?'Em menos de 1h':c.at-now<86400000?'Em '+Math.ceil((c.at-now)/3600000)+'h':'Em '+Math.ceil((c.at-now)/86400000)+' dias'}));
}
export function programmingRows(items,esc){return items.map(c=>`<tr><td><button type="button" ${c.kind==='content'?'data-action="content-detail"':'data-chat="program-detail"'} data-id="${esc(c.id)}" title="${esc(c.title)}">${esc(c.title)}</button><small>${esc(c.format)}</small></td><td><span>${esc(new Date(c.at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}))}</span><small>${c.kind==='generation'?'Gerar':'Postar'} · ${esc(new Date(c.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}</small><small>${esc(c.remaining)}</small></td><td><span class="program-status ${c.tone}">${esc(c.label)}</span></td></tr>`).join('');}
